* { box-sizing: border-box; }

:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  color: #24332d;
  background: #e9f2e8;
}

body {
  min-height: 100vh;
  margin: 0;
  display: grid;
  place-items: center;
  padding: 20px;
  background: radial-gradient(circle at 20% 15%, #f8f3dc 0, transparent 38%), #e9f2e8;
}

.game-card {
  width: min(100%, 470px);
  padding: clamp(22px, 6vw, 38px);
  text-align: center;
  background: #fffdf5;
  border: 3px solid #24332d;
  border-radius: 18px;
  box-shadow: 8px 8px 0 #b8cdb8;
}

.eyebrow { margin: 0 0 8px; color: #52725b; font-size: .85rem; font-weight: 800; letter-spacing: .13em; }
h1 { margin: 0; font-size: clamp(1.7rem, 7vw, 2.25rem); line-height: 1.15; }
.instructions { margin: 10px 0 24px; color: #52645a; }

.scoreboard {
  display: flex;
  justify-content: center;
  gap: 14px;
  margin-bottom: 20px;
}
.scoreboard p { min-width: 112px; margin: 0; padding: 10px 16px; background: #e9f2e8; border: 2px solid #b8cdb8; border-radius: 10px; font-weight: 700; }
.scoreboard strong { margin-left: 6px; color: #bd5738; font-size: 1.25rem; }

.board {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(8px, 3vw, 14px);
  width: min(100%, 340px);
  margin: 0 auto;
  padding: clamp(12px, 4vw, 18px);
  background: #c8ddc5;
  border: 3px solid #24332d;
  border-radius: 14px;
}

.hole {
  aspect-ratio: 1;
  min-width: 0;
  padding: 0;
  overflow: hidden;
  cursor: pointer;
  background: #6c8d68;
  border: 3px solid #24332d;
  border-radius: 50%;
  box-shadow: inset 0 5px 0 #52725b;
  transition: transform .12s, background .12s, box-shadow .12s;
}
.hole span { display: block; width: 58%; height: 58%; margin: auto; border-radius: 50%; background: transparent; transition: transform .12s; }
.hole.has-mole { background: #f0c86e; box-shadow: inset 0 5px 0 #d49b4b; }
.hole.has-mole span { background: #bd5738; border: 3px solid #24332d; box-shadow: inset 0 7px 0 #e9956e; transform: translateY(-2px); }
.hole:disabled { cursor: default; }
.hole:not(:disabled):hover { transform: scale(1.04); }
.hole:not(:disabled):active { transform: scale(.94); }
.hole:focus-visible, .start-button:focus-visible { outline: 4px solid #bd5738; outline-offset: 4px; }

.message { min-height: 1.5em; margin: 18px 0 12px; color: #52645a; font-weight: 650; }
.start-button {
  min-width: 150px;
  padding: 12px 24px;
  color: #fffdf5;
  background: #bd5738;
  border: 2px solid #24332d;
  border-radius: 10px;
  box-shadow: 0 4px 0 #873e2a;
  font: inherit;
  font-weight: 800;
  cursor: pointer;
  transition: transform .12s, box-shadow .12s, background .12s;
}
.start-button:hover { background: #a9472d; }
.start-button:active { transform: translateY(3px); box-shadow: 0 1px 0 #873e2a; }

@media (max-width: 380px) {
  body { padding: 12px; }
  .game-card { padding: 20px 14px; }
  .scoreboard { gap: 8px; }
  .scoreboard p { min-width: 0; flex: 1; }
}

const holes = [...document.querySelectorAll('.hole')];
const scoreDisplay = document.querySelector('#score');
const timeDisplay = document.querySelector('#time');
const message = document.querySelector('#message');
const startButton = document.querySelector('#start');

let score = 0;
let timeLeft = 30;
let activeHole = -1;
let gameTimer;
let moleTimer;

function clearMole() {
  holes.forEach((hole, index) => {
    hole.classList.remove('has-mole');
    hole.setAttribute('aria-label', `Hole ${index + 1}, empty`);
  });
  activeHole = -1;
}

function showMole() {
  clearMole();
  activeHole = Math.floor(Math.random() * holes.length);
  holes[activeHole].classList.add('has-mole');
  holes[activeHole].setAttribute('aria-label', `Hole ${activeHole + 1}, mole!`);
}

function endGame() {
  clearInterval(gameTimer);
  clearInterval(moleTimer);
  clearMole();
  holes.forEach(hole => { hole.disabled = true; });
  startButton.disabled = false;
  startButton.textContent = 'Play again';
  message.textContent = `Game over! Final score: ${score}`;
}

function startGame() {
  clearInterval(gameTimer);
  clearInterval(moleTimer);
  score = 0;
  timeLeft = 30;
  scoreDisplay.textContent = score;
  timeDisplay.textContent = timeLeft;
  message.textContent = 'Catch as many as you can!';
  startButton.disabled = true;
  startButton.textContent = 'Playing…';
  holes.forEach(hole => { hole.disabled = false; });
  showMole();
  moleTimer = setInterval(showMole, 1000);
  gameTimer = setInterval(() => {
    timeLeft -= 1;
    timeDisplay.textContent = timeLeft;
    if (timeLeft === 0) endGame();
  }, 1000);
}

holes.forEach((hole, index) => {
  hole.addEventListener('click', () => {
    if (index !== activeHole || timeLeft === 0) return;
    score += 1;
    scoreDisplay.textContent = score;
    showMole();
  });
});

startButton.addEventListener('click', startGame);
